        if (Lo.IsTop || Hi.IsTop) return false;
        mid = (Lo.Value + Hi.Value) / 2.0;
        range = (double)Hi.Value - Lo.Value;
        return true;
    }

    /// <summary>§3.3.1 调试字符串（无代数语义，仅区间表示）。</summary>
    public override string ToString() => $"[{Lo},{Hi}]";
}

